use std::fs::{self, File, OpenOptions};
use std::io::{self, Write, Read};
use std::path::{Path, PathBuf};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::os::unix::fs::OpenOptionsExt;

#[derive(Debug, Clone, PartialEq)]
pub enum Role {
    Admin,
    ReadWrite,
    ReadOnly,
    Auditor,
}

#[derive(Debug, Clone)]
pub struct Session {
    pub user_id: String,
    pub role: Role,
    pub db_name: String,
}

pub struct QueryCache {
    base_dir: PathBuf,
    sessions: Arc<Mutex<HashMap<String, Session>>>,
}

impl QueryCache {
    pub fn new(base_dir: &str) -> io::Result<Self> {
        let path = PathBuf::from(base_dir);
        fs::create_dir_all(&path)?;
        // Restrict base directory permissions
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(&path, fs::Permissions::from_mode(0o700))?;
        }
        Ok(QueryCache {
            base_dir: path,
            sessions: Arc::new(Mutex::new(HashMap::new())),
        })
    }

    pub fn register_session(&self, token: &str, session: Session) {
        let mut sessions = self.sessions.lock().unwrap();
        sessions.insert(token.to_string(), session);
    }

    fn check_permission(&self, token: &str, requires_write: bool) -> Result<Session, String> {
        let sessions = self.sessions.lock().unwrap();
        let session = sessions.get(token)
            .ok_or_else(|| "Invalid session token".to_string())?;

        if requires_write {
            match session.role {
                Role::Admin | Role::ReadWrite => Ok(session.clone()),
                _ => Err("Insufficient permissions for write operation".to_string()),
            }
        } else {
            Ok(session.clone())
        }
    }

    fn validate_component(s: &str) -> Result<(), String> {
        if s.contains('/') || s.contains('\\') || s.contains("..")
            || s.contains('\0') || s.is_empty() || s.len() > 64 {
            return Err("Invalid path component".to_string());
        }
        if !s.chars().all(|c| c.is_alphanumeric() || c == '_' || c == '-') {
            return Err("Invalid characters in component".to_string());
        }
        Ok(())
    }

    fn derive_cache_path(&self, session: &Session, query_hash: &str) -> Result<PathBuf, String> {
        Self::validate_component(&session.db_name)?;
        Self::validate_component(&session.user_id)?;
        Self::validate_component(query_hash)?;

        let db_dir = self.base_dir.join(&session.db_name);
        let _ = fs::create_dir_all(&db_dir);
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&db_dir, fs::Permissions::from_mode(0o700));
        }
        Ok(db_dir.join(format!("cache_{}_{}", session.user_id, query_hash)))
    }

    /// Materializes a query result to a temporary file for large result sets.
    /// The temp file is created with restricted permissions, then atomically renamed.
    pub fn materialize_result(
        &self,
        token: &str,
        query_hash: &str,
        data: &[u8],
    ) -> Result<PathBuf, String> {
        let session = self.check_permission(token, false)?;
        let cache_path = self.derive_cache_path(&session, query_hash)?;

        // Create temporary file for atomic write with restricted permissions
        let temp_path = self.create_temp_file(&session, query_hash)?;

        // Write data to temp file
        let mut file = OpenOptions::new()
            .write(true)
            .open(&temp_path)
            .map_err(|e| format!("Failed to open temp file: {}", e))?;

        file.write_all(data)
            .map_err(|e| format!("Failed to write data: {}", e))?;

        // Rename temp to final cache path
        fs::rename(&temp_path, &cache_path)
            .map_err(|e| format!("Failed to finalize cache: {}", e))?;

        Ok(cache_path)
    }

    fn create_temp_file(&self, session: &Session, query_hash: &str) -> Result<PathBuf, String> {
        Self::validate_component(&session.db_name)?;
        Self::validate_component(&session.user_id)?;
        Self::validate_component(query_hash)?;

        let db_dir = self.base_dir.join(&session.db_name);
        let _ = fs::create_dir_all(&db_dir);
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&db_dir, fs::Permissions::from_mode(0o700));
        }

        // Generate temp filename with random suffix for unpredictability
        let random_suffix: u64 = rand_u64();
        let temp_name = format!(".tmp_{}_{}_{:016x}", session.user_id, query_hash, random_suffix);
        let temp_path = db_dir.join(&temp_name);

        // Create file with owner-only permissions (mode 0600)
        OpenOptions::new()
            .write(true)
            .create_new(true)  // Fail if file exists - prevents symlink attacks
            .mode(0o600)
            .open(&temp_path)
            .map_err(|e| format!("Failed to create temp file: {}", e))?;

        Ok(temp_path)
    }

    pub fn read_cached(
        &self,
        token: &str,
        query_hash: &str,
    ) -> Result<Vec<u8>, String> {
        let session = self.check_permission(token, false)?;
        let cache_path = self.derive_cache_path(&session, query_hash)?;

        if !cache_path.exists() {
            return Err("Cache miss".to_string());
        }

        let mut file = File::open(&cache_path)
            .map_err(|e| format!("Failed to open cache: {}", e))?;
        let mut buf = Vec::new();
        file.read_to_end(&mut buf)
            .map_err(|e| format!("Failed to read cache: {}", e))?;
        Ok(buf)
    }

    pub fn invalidate_cache(
        &self,
        token: &str,
        query_hash: &str,
    ) -> Result<(), String> {
        let session = self.check_permission(token, true)?;
        let cache_path = self.derive_cache_path(&session, query_hash)?;

        if cache_path.exists() {
            fs::remove_file(&cache_path)
                .map_err(|e| format!("Failed to remove cache: {}", e))?;
        }
        Ok(())
    }

    /// Audit log for compliance - writes query metadata
    pub fn log_query_audit(
        &self,
        token: &str,
        query_hash: &str,
        query_text: &str,
    ) -> Result<(), String> {
        let session = self.check_permission(token, false)?;
        Self::validate_component(&session.db_name)?;

        let audit_dir = self.base_dir.join("audit");
        let _ = fs::create_dir_all(&audit_dir);
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = fs::set_permissions(&audit_dir, fs::Permissions::from_mode(0o700));
        }

        let audit_path = audit_dir.join(format!("audit_{}.log", session.db_name));
        let mut file = OpenOptions::new()
            .create(true)
            .append(true)
            .mode(0o600)
            .open(&audit_path)
            .map_err(|e| format!("Audit log error: {}", e))?;

        // Sanitize query_text to prevent log injection
        let sanitized_query: String = query_text.chars()
            .map(|c| if c == '\n' || c == '\r' { ' ' } else { c })
            .collect();

        let entry = format!(
            "user={} role={:?} hash={} query={}\n",
            session.user_id, session.role, query_hash, sanitized_query
        );
        file.write_all(entry.as_bytes())
            .map_err(|e| format!("Audit write error: {}", e))?;

        Ok(())
    }
}

/// Simple PRNG for temp file naming - not cryptographic but sufficient for uniqueness
fn rand_u64() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .subsec_nanos() as u64;
    let tid = std::thread::current().id();
    let tid_hash = format!("{:?}", tid).len() as u64;
    nanos.wrapping_mul(6364136223846793005).wrapping_add(tid_hash ^ 0xdeadbeefcafe1234)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_materialize_and_read() {
        let cache = QueryCache::new("/tmp/dbdriver_test_secure").unwrap();
        let session = Session {
            user_id: "user1".to_string(),
            role: Role::ReadWrite,
            db_name: "testdb".to_string(),
        };
        cache.register_session("tok1", session);

        let data = b"SELECT * FROM users";
        let path = cache.materialize_result("tok1", "abc123", data).unwrap();
        assert!(path.exists());

        let result = cache.read_cached("tok1", "abc123").unwrap();
        assert_eq!(result, data);
    }

    #[test]
    fn test_readonly_cannot_invalidate() {
        let cache = QueryCache::new("/tmp/dbdriver_test_secure2").unwrap();
        let session = Session {
            user_id: "viewer".to_string(),
            role: Role::ReadOnly,
            db_name: "testdb".to_string(),
        };
        cache.register_session("tok2", session);

        let result = cache.invalidate_cache("tok2", "abc123");
        assert!(result.is_err());
    }

    #[test]
    fn test_path_traversal_rejected() {
        let cache = QueryCache::new("/tmp/dbdriver_test_secure3").unwrap();
        let session = Session {
            user_id: "../etc".to_string(),
            role: Role::ReadWrite,
            db_name: "testdb".to_string(),
        };
        cache.register_session("tok3", session);

        let result = cache.materialize_result("tok3", "abc123", b"data");
        assert!(result.is_err());
    }
}
